insert into products(id,category_id,brand_id,slug,name,japanese_name,series,description,description_it,metadata) values('6f989d2f-58e1-5f0a-be6a-9553f11c85dc','cd755fcb-2bc5-5975-8ec0-f45e7df891cc','382feca9-48e9-5144-a92d-41f77fb7e438','neo-vqs','Neo-VQS','ネオVQS','Racing Mini 4WD','The Neo-VQS family reinterprets the Vanquish Jr. across VZ and VS chassis, from the 2020 standard kit to event specials, collaboration models and Advanced Packs.','La famiglia Neo-VQS riprende la Vanquish Jr. attraverso telai VZ e VS, dal kit standard del 2020 alle speciali per eventi, alle collaborazioni e agli Advanced Pack.','{"launch_status": "coming_soon", "family_audit": {"checked_at": "2026-11-24", "kit_release_count": 7, "status": "staged_initial_market_audit"}}') on conflict(id) do nothing;
insert into product_releases(id,product_id,item_number,release_type,edition_name,release_year,release_date,chassis,barcode_jan,color,country_market,rarity,edition_type,description,description_it,notes,production_status,verification_status,catalog_visibility,is_original,data_source,status_checked_at) values('01e1ea1d-0513-5562-8e55-63c11f24fbe5','6f989d2f-58e1-5f0a-be6a-9553f11c85dc','18094','Original','Neo-VQS (VZ Chassis)',2020,'2020-03-28','VZ','4950344180943','Black / red wheels','International','Common','original','The original Neo-VQS introduced the VZ chassis in March 2020. Its angular black ABS body reinterprets the Vanquish Jr., with red five-spoke wheels, low-profile tires and 3.5:1 gears.','La Neo-VQS originale introduce il telaio VZ nel marzo 2020. La carrozzeria angolare in ABS nero riprende la Vanquish Jr., con cerchi rossi a cinque razze, gomme a basso profilo e rapporto 3,5:1.','Audited 2026-11-24. Exact complete-kit identity and dedicated images reviewed. No guessed sale prices, Italian delivered cost, barcode or rarity. Same-SKU restocks retained as production waves.','active','verified','public',true,'neo_vqs_audit_20261124',now()) on conflict(id) do nothing;
