insert into product_releases(id,product_id,item_number,release_type,edition_name,release_year,release_date,chassis,barcode_jan,color,country_market,rarity,edition_type,description,description_it,notes,production_status,verification_status,catalog_visibility,is_original,data_source,status_checked_at) values('51267c3e-03cc-54c4-8b9b-1c4e413d75b8','6f989d2f-58e1-5f0a-be6a-9553f11c85dc','95598','Special Edition','Neo-VQS Advanced Pack (2020)',2020,null,'VZ','4950344955985','Smoke / black chassis / yellow wheels','International','Common','special','Advanced Pack first introduced in December 2020, with a smoke ABS body, black VZ chassis, clear-yellow A parts and yellow wheels. Includes a Light-Dash motor, FRP stays, brakes, side mass dampers and 3.7:1 gears. The July 2023 production is retained within this edition; the later item #18106 has its own catalog record.','Advanced Pack introdotto nel dicembre 2020, con carrozzeria ABS fumé, telaio VZ nero, parti A giallo trasparente e cerchi gialli. Include motore Light-Dash, supporti FRP, freni, mass damper laterali e rapporto 3,7:1. La produzione del luglio 2023 appartiene a questa edizione; il successivo articolo #18106 ha una scheda distinta.','Audited 2026-11-24. Exact complete-kit identity and dedicated images reviewed. No guessed sale prices, Italian delivered cost, barcode or rarity. Same-SKU restocks retained as production waves.','discontinued','verified','public',false,'neo_vqs_audit_20261124',now()) on conflict(id) do nothing;
