insert into product_releases(id,product_id,item_number,release_type,edition_name,release_year,release_date,chassis,barcode_jan,color,country_market,rarity,edition_type,description,description_it,notes,production_status,verification_status,catalog_visibility,is_original,data_source,status_checked_at) values('44d94956-6bbd-5a46-ae0c-e1f309254726','6f989d2f-58e1-5f0a-be6a-9553f11c85dc','95633','Special Edition','Neo-VQS Polycarbonate Body Special (VS Chassis)',2021,null,'VS','4950344956333','Clear polycarbonate / turquoise chassis / white tires','Japan / International','Uncommon','special','Complete kit on the compact VS chassis, with a clear polycarbonate body, carbon-reinforced Y-spoke wheels and white hard low-profile tires. Initially an event item associated with Japan Cup 2021; wider Japanese Mini 4WD Station distribution followed on 31 March 2022. Both distributions remain one edition.','Kit completo su telaio VS compatto, con carrozzeria in policarbonato trasparente, cerchi a Y rinforzati al carbonio e gomme hard bianche a basso profilo. Inizialmente legato agli eventi Japan Cup 2021, arriva nella distribuzione giapponese Mini 4WD Station il 31 marzo 2022. Le due distribuzioni restano una sola edizione.','Audited 2026-11-24. Exact complete-kit identity and dedicated images reviewed. No guessed sale prices, Italian delivered cost, barcode or rarity. Same-SKU restocks retained as production waves. First event distribution in 2021 supported by contemporary genealogy; 2022-03-31 is wider distribution, not a separate kit.','discontinued','verified','public',false,'neo_vqs_audit_20261124',now()) on conflict(id) do nothing;
